function momentScene(card, id, rnd) {
  const [p, s, a] = card.colors;
  const isBike = card.sport === 'motogp' || card.id.includes('rossi') || card.id.includes('marquez') || card.id.includes('doohan');
  const isCross = card.sport === 'crossover';
  const yr = card.year || '';
  let out = `<g>
    <text x="180" y="300" font-family="'Barlow Condensed',sans-serif" font-size="150" font-weight="800" font-style="italic" text-anchor="middle" fill="${rgba('#fff',.05)}" letter-spacing="-4">${esc(yr)}</text>
