326: function generatePull(pack, forcedFinish = null) {
327:   const pool = packPool(pack);
328:   const rnd = Math.random;
329:   const owned = new Set(state.items.map(i => i.cardId));
330:   const picks = [];
331:   const used = new Set();
332:   const floors = pack.guarantees || {};
333:   const allFloor = Object.entries(floors).reduce((best, [rar, n]) => (n >= pack.cards && RANK[rar] > RANK[best] ? rar : best), 'common');
334: 
335:   for (let slot = 0; slot < pack.cards; slot++) {
336:     let rarity;
337:     if (slot < (pack.guaranteeNew || 0) && owned.size < 300) {
338:       rarity = rollRarity(pack, rnd);
339:       let card = cardOfRarity(pool, rarity, used, true, owned, rnd);
340:       if (!card) card = cardOfRarity(pool, rarity, used, false, owned, rnd);
341:       if (card) {
342:         picks.push({card, new: !owned.has(card.id)});
343:         used.add(card.id);
344:         continue;
345:       }
346:     }
347:     rarity = rollRarity(pack, rnd);
348:     if (RANK[rarity] < RANK[allFloor]) rarity = allFloor;
349:     let card = cardOfRarity(pool, rarity, used, false, owned, rnd);
350:     if (!card) card = cardOfRarity(pool, rarity, used, false, owned, rnd);
351:     if (!card) card = pool.find(c => !used.has(c.id)) || pool[0];
352:     picks.push({card, new: !owned.has(card.id)});
353:     used.add(card.id);
354:   }
355: 
356:   // rarity floor guarantees
357:   for (const [rar, need] of Object.entries(floors)) {
358:     let have = picks.filter(p => RANK[p.card.rarity] >= RANK[rar]).length;
359:     while (have < need) {
360:       const target = picks.reduce((low, p, idx) => (RANK[p.card.rarity] < RANK[picks[low].card.rarity] ? idx : low), 0);
361:       const exclude = new Set(picks.filter((_,i)=>i!==target).map(p => p.card.id));
362:       let card = cardOfRarity(pool, rar, exclude, true, owned, rnd);
363:       if (!card) {
364:         // find any card at or above rarity
365:         const order = ['common','rare','epic','legendary','iconic'];
366:         for (let r = RANK[rar]; r <= 4 && !card; r++) card = cardOfRarity(pool, order[r], exclude, false, owned, rnd);
367:       }
368:       if (!card) break;
369:       picks[target] = {card, new: !owned.has(card.id)};
370:       have = picks.filter(p => RANK[p.card.rarity] >= RANK[rar]).length;
371:     }
372:   }
373: 
374:   // guarantee new cards remaining
375:   let newCount = picks.filter(p => p.new).length;
376:   for (let i = 0; i < picks.length && newCount < (pack.guaranteeNew || 0); i++) {
377:     if (picks[i].new) continue;
378:     const exclude = new Set(picks.map(p => p.card.id));
379:     let card = cardOfRarity(pool, picks[i].card.rarity, exclude, true, owned, rnd);
380:     if (!card && RANK[allFloor] > 0) card = cardOfRarity(pool, allFloor, exclude, true, owned, rnd);
381:     if (card) { picks[i] = {card, new: true}; newCount++; }
382:   }
383: 
384:   // crossover guarantee
385:   if (pack.scope === 'crossover') {
386:     const hasX = picks.some(p => p.card.sport === 'crossover');
387:     if (!hasX) {
388:       const xPool = CARDS.filter(c => c.sport === 'crossover');
389:       const xCard = xPool[Math.floor(rnd() * xPool.length)];
390:       const idx = picks.reduce((low, p, i) => RANK[p.card.rarity] < RANK[picks[low].card.rarity] ? i : low, 0);
391:       picks[idx] = {card: xCard, new: !owned.has(xCard.id)};
392:     }
393:   }
394: 
395:   let result = picks.map(p => {
396:     let finish = rollFinish(pack, p.card, rnd);
397:     if (finish === 'base' && forcedFinish) finish = forcedFinish;
398:     return {card: p.card, finish, isNew: p.new, serial: null};
399:   });
400:   if (pack.guaranteedFinish) {
401:     const idx = result.reduce((best, r, i) => RANK[r.card.rarity] > RANK[result[best].card.rarity] ? i : best, 0);
402:     result[idx].finish = pack.guaranteedFinish;
403:   }
404:   for (const r of result) {
405:     if (r.finish === 'numbered') r.serial = serialFor(r.card);
406:   }
407:   return result;
408: }
