487: export function dailyStatus() {
488:   ensureToday();
489:   const today = todayKey();
490:   const claimedToday = state.daily.lastClaim === today;
491:   const streak = state.daily.streak;
492:   const cycleDay = claimedToday ? ((streak - 1) % 7) + 1 : (streak % 7) + 1;
493:   const canClaim = !claimedToday;
494:   return {
495:     canClaim,
496:     streak,
497:     cycleDay,
498:     claimedToday,
499:     nextDay: cycleDay,
