61: export function challengeForToday(date = new Date()) {
62:   // deterministic 3-challenge rotation, stable within the calendar day
63:   const seed = parseInt(localDateKey(date).replace(/-/g, ''), 10);
64:   const pool = [...DAILY_CHALLENGE_POOL];
65:   const picks = [];
66:   let s = seed;
67:   while (picks.length < 3 && pool.length) {
68:     s = (s * 9301 + 49297) % 233280;
69:     const idx = s % pool.length;
70:     picks.push(pool.splice(idx, 1)[0]);
71:   }
72:   return picks;
73: }
