.ovr b{font-size:8.2cqw;letter-spacing:-.02em;font-weight:800;color:#fff;text-shadow:0 1px 0 rgba(0,0,0,.6)}
.ovr i{font-family:var(--font-tech);font-style:normal;font-size:2.1cqw;font-weight:700;letter-spacing:.12em;color:var(--muted);margin-top:.7cqw}
.r-legendary .ovr b{color:var(--gold);text-shadow:0 0 12px rgba(255,194,71,.5)}
.r-iconic .ovr b{background:linear-gradient(180deg,#fff,#ffb8ee);-webkit-background-clip:text;background-clip:text;color:transparent}
.card-tags{display:flex;flex-direction:column;align-items:flex-end;gap:.9cqw}
.card-tag{display:flex;align-items:center;gap:.8cqw;height:3.6cqw;padding:0 1.4cqw;border-radius:99px;background:rgba(3,5,8,.72);border:.4px solid rgba(255,255,255,.16);font-family:var(--font-tech);font-weight:700;font-size:2.15cqw;letter-spacing:.14em;text-transform:uppercase;color:#dbe2ee;backdrop-filter:blur(4px)}
.card-tag.sport-f1{color:#ff9da1;border-color:rgba(255,47,56,.4)}
.card-tag.sport-motogp{color:#88f0ff;border-color:rgba(34,211,238,.4)}
.card-tag.era{font-size:2cqw;letter-spacing:.1em;color:#aab3c4}
.card-tag.rarity{color:var(--rarity);border-color:color-mix(in srgb,var(--rarity) 40%, transparent);background:rgba(3,5,8,.65)}

/* bottom info */
.card-info{position:absolute;left:0;right:0;bottom:0;z-index:7;padding:0 4cqw 3.4cqw;display:flex;flex-direction:column;gap:.5cqw}
.card-kicker{display:flex;align-items:center;gap:1.4cqw;font-family:var(--font-tech);font-weight:700;font-size:2.15cqw;letter-spacing:.15em;text-transform:uppercase;color:#c6cfdd;text-shadow:0 1px 3px #000}
.card-kicker .num{color:var(--rarity);letter-spacing:.04em;font-size:2.5cqw}
.card-kicker .dotsep{width:.6cqw;height:.6cqw;border-radius:50%;background:var(--rarity);opacity:.8}
.card-name{font-family:var(--font-display);font-weight:800;font-size:8.3cqw;line-height:.86;letter-spacing:.005em;text-transform:uppercase;color:#fff;text-shadow:0 2px 10px rgba(0,0,0,.75);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.card-name.long{font-size:7.1cqw}
.card-role{font-family:var(--font-tech);font-weight:600;font-size:2.15cqw;letter-spacing:.17em;text-transform:uppercase;color:#9aa4b6;display:flex;align-items:center;gap:1.2cqw;margin-top:.3cqw}
.card-role .flag{width:3.4cqw;height:2.4cqw;border-radius:.5cqw;box-shadow:0 0 0 .3px rgba(255,255,255,.25)}
.card-statline{display:grid;grid-template-columns:repeat(4,1fr);gap:0;margin-top:1.6cqw;border-top:.5px solid rgba(255,255,255,.14);border-bottom:.5px solid rgba(255,255,255,.14);padding:1.4cqw 0;background:linear-gradient(90deg,rgba(255,255,255,.03),rgba(255,255,255,0))}
