409: /* ---------- team crest ---------- */
410: function teamMonogram(name) {
411:   const skip = new Set(['racing','team','grand','prix','scuderia','factory','formula','motorsport','bwt','amg','petronas','reparto','corse','aramco','stake','kick','red','bull']);
412:   const words = name.replace(/[^a-zA-Z ]/g,' ').split(/\s+/).filter(Boolean);
413:   const meaningful = words.filter(w => !skip.has(w.toLowerCase()));
414:   const src = meaningful.length ? meaningful : words;
415:   if (src.length >= 2) return (src[0][0] + src[1][0]).toUpperCase();
416:   return (src[0] || 'GP').slice(0,2).toUpperCase();
417: }
