    <path d="M120 400l18-19 34 10 14 106-42 7z" fill="${dark(a,.4)}" opacity=".8"/>
    <path d="M100 504l24-97 16 4-16 93z" fill="${rgba('#fff',.08)}"/>
    <path d="M260 504l-24-97-16 4 16 93z" fill="${rgba('#fff',.06)}"/>
    <path d="M142 378c12 20 34 30 58 30s46-10 58-30" fill="none" stroke="${rgba('#fff',.18)}" stroke-width="3"/>
    <rect x="248" y="400" width="56" height="22" rx="4" fill="${rgba('#050608',.8)}" stroke="${rgba(a,.5)}"/>
