411: export function openPack(packId) {
412:   ensureToday();
413:   const today = todayKey();
414:   let pack;
415:   if (packId === 'potd') {
416:     pack = getPackOfTheDay(new Date());
417:     if (state.potd.purchases >= 3) throw gameError('POTD_LIMIT', 'Daily limit reached for Pack of the Day');
418:   } else {
419:     pack = PACK_MAP[packId];
420:   }
421:   if (!pack) throw gameError('NO_PACK', 'Unknown pack');
422:   if (pack.oncePerDay && state.dailyPackDate === today) throw gameError('DAILY_USED', 'Daily Pack already claimed today');
423:   if (packId === 'potd' && state.coins < pack.cost && !state.tokens.includes('potd')) {
424:     throw gameError('NOT_ENOUGH_COINS', 'Not enough coins');
425:   }
426: 
427:   let usedToken = false;
428:   const tokenIdx = state.tokens.indexOf(packId);
429:   if (tokenIdx >= 0 && packId !== 'potd') {
430:     state.tokens.splice(tokenIdx, 1);
431:     usedToken = true;
432:     state.tokensUsed++;
433:   } else {
434:     spendCurrency(pack.currency, pack.cost);
435:   }
436: 
437:   const pulls = generatePull(pack);
438:   const results = [];
439:   for (const p of pulls) {
440:     const item = addItem(p.card.id, p.finish, {serial: p.serial, source: packId});
441:     const value = cardValue(p.card, p.finish);
442:     results.push({...p, item, value});
443:     state.stats.cardsPulled++;
444:     if (p.isNew) { state.daily.newCards++; }
445:     if (RANK[p.card.rarity] >= 2) state.stats.epicPulls++;
446:     if (RANK[p.card.rarity] >= 2) state.daily.epicPulls++;
447:     if (RANK[p.card.rarity] >= 3) { state.stats.legendaryPulls++; state.daily.legendaryPulls++; }
448:     if (RANK[p.card.rarity] >= 4) state.stats.iconicPulls++;
449:     state.recentPulls.unshift({cardId: p.card.id, finish: p.finish, serial: p.serial, isNew: p.isNew, at: Date.now(), uid: item.uid});
450:   }
451:   state.recentPulls = state.recentPulls.slice(0, 24);
452:   state.stats.packsOpened++;
453:   state.daily.packsOpened++;
454:   if (pack.oncePerDay) state.dailyPackDate = today;
455:   if (packId === 'daily') { state.stats.dailyPacks++; state.daily.dailyPacks++; }
456:   if (packId === 'gold' || packId === 'f1-gold' || packId === 'motogp-gold') { state.stats.goldPacks++; state.daily.goldPacks++; }
457:   if (packId === 'potd') state.potd.purchases++;
458:   const xpGain = 30 + results.reduce((s, r) => s + (r.isNew ? 12 : 2) + ({common:0,rare:2,epic:8,legendary:18,iconic:45}[r.card.rarity] || 0), 0);
459:   const levelUps = addXp(xpGain);
460:   if (state.stats.maxUnique < uniqueCount()) state.stats.maxUnique = uniqueCount();
461:   save(); emit();
462:   return {pack, results, usedToken, currency: pack.currency, amount: pack.cost, levelUps, xpGain};
463: }
