429: function teamMonogram(name) {
430:   const skip = new Set(['racing','team','grand','prix','scuderia','factory','formula','motorsport','bwt','amg','petronas','reparto','corse','aramco','stake','kick','red','bull']);
431:   const words = name.replace(/[^a-zA-Z ]/g,' ').split(/\s+/).filter(Boolean);
432:   const meaningful = words.filter(w => !skip.has(w.toLowerCase()));
433:   const src = meaningful.length ? meaningful : words;
434:   if (src.length >= 2) return (src[0][0] + src[1][0]).toUpperCase();
435:   return (src[0] || 'GP').slice(0,2).toUpperCase();
436: }
