492:   const streakAlive = claimedToday || state.daily.lastClaim === yesterdayKey();
493:   const streak = streakAlive ? Math.max(0, Number(state.daily.streak) || 0) : 0;
494:   const nextStreak = claimedToday ? Math.max(1, streak) : Math.max(1, streak + 1);
495:   const cycleDay = ((nextStreak - 1) % 7) + 1;
496:   const canClaim = !claimedToday;
497:   return {
498:     canClaim,
499:     streak,
500:     cycleDay,
501:     claimedToday,
502:     nextDay: cycleDay,
503:     rewards: DAILY_REWARDS,
504:     claimedCount: canClaim ? (cycleDay - 1) : cycleDay,
505:     packAvailable: state.dailyPackDate !== today,
506:   };
