512:   state.daily.streak = state.daily.lastClaim === yesterdayKey() ? state.daily.streak + 1 : 1;
513:   state.daily.lastClaim = today;
514:   if (state.daily.streak > state.stats.bestStreak) state.stats.bestStreak = state.daily.streak;
515:   const day = ((state.daily.streak - 1) % 7) + 1;
516:   const reward = DAILY_REWARDS[day - 1];
