519:   state.stats.coinsEarned += reward.coins || 0;
520:   if (reward.pack) state.tokens.push(reward.pack);
521:   const levelUps = addXp(50);
522:   save(); emit();
523:   return {reward, day, streak: state.daily.streak, levelUps};
