.reveal-rays.spin{animation:raysIn 1.1s ease-out both, raysSpin 30s linear infinite}
.reveal-tagline{position:relative;z-index:5;display:flex;align-items:center;gap:9px;font-family:var(--font-tech);font-weight:700;font-size:10px;letter-spacing:.3em;text-transform:uppercase;color:var(--tagc,var(--muted));text-shadow:0 0 20px rgba(0,0,0,.8);animation:tagDrop .5s .25s both;height:16px}
.reveal-tagline .ln{width:22px;height:1px;background:currentColor;opacity:.6}
.reveal-card-holder{position:relative;z-index:4;width:clamp(216px,25vw,300px);perspective:1200px;animation:cardSlam .75s cubic-bezier(.18,.9,.25,1.12) both}
.reveal-card-holder .card{box-shadow:0 40px 80px -30px #000, 0 0 70px -15px var(--rarity-glow)}
.reveal-meta{position:relative;z-index:5;display:flex;flex-direction:column;align-items:center;gap:4px;animation:metaUp .5s .3s both;min-height:44px;text-align:center}
