754: export function tradeOffers() {
755:   const rnd = rngFrom(9001 + state.tradeSeed * 3517);
756:   const groups = groupedCollection().filter(g => g.count > 1);
757:   const offers = [];
758:   if (!groups.length) return offers;
759:   const dupes = [];
760:   for (const g of groups) {
761:     // Keep the best finish; offer the lowest-value spare copy in a trade.
762:     const copies = [...g.items].sort((a,b) => FINISH_ORDER.indexOf(a.finish) - FINISH_ORDER.indexOf(b.finish));
763:     const spare = copies[0];
764:     dupes.push({group: g, item: spare, value: cardValue(g.card, spare.finish)});
765:   }
766:   const owned = new Set(state.items.map(i => i.cardId));
767:   const offeredIds = new Set();
