771:     if (!d || usedDupes.has(d.item.uid)) continue;
772:     usedDupes.add(d.item.uid);
773:     const wantRank = RANK[d.group.card.rarity];
774:     const bump = rnd() > .8 ? 1 : 0;
775:     const targetRank = Math.min(4, wantRank + bump);
776:     const rarities = ['common','rare','epic','legendary','iconic'];
777:     let candidates = CARDS.filter(c => !owned.has(c.id) && !offeredIds.has(c.id) && RANK[c.rarity] === targetRank);
778:     if (!candidates.length) candidates = CARDS.filter(c => !owned.has(c.id) && !offeredIds.has(c.id) && Math.abs(RANK[c.rarity] - wantRank) <= 1);
779:     if (!candidates.length) candidates = CARDS.filter(c => !owned.has(c.id) && !offeredIds.has(c.id));
780:     if (!candidates.length) break;
781:     const offerCard = candidates[Math.floor(rnd() * candidates.length)];
782:     offeredIds.add(offerCard.id);
783:     const offerValue = cardValue(offerCard, 'base');
784:     const ratio = offerValue / Math.max(1, d.value);
