function hash32(str) {
  let h = 2166136261;
  for (...) ...
  return h >>> 0;
}
const TAU = Math.PI * 2;
function phase(cardId, salt = '') { return (hash32(cardId + salt) / 4294967296) * TAU; }

const RARITY_VOL = {common:.06, rare:.085, epic:.12, legendary:.17, iconic:.24};

function sentiment(t) {
  return Math.sin(t / 97 + 1.7) * .55 + Math.sin(t / 41 + .3) * .3 + Math.sin(t / 17.3) * .15;
}

function tickJitter(cardId, now) {
  const b = Math.floor(now / 20000);
  return ((hash32(cardId + 'tick' + b) % 2000) / 1000 - 1) * .35; // -0.35..0.35
}

export function marketFactor(card, finish='base', now=Date.now()) {
  const t = now / 60000;
  const p = phase(card.id + finish);
  const vol = (RARITY_VOL[card.rarity] || .08) * (finish === 'base' ? 1 : .85);
  const wave = Math.sin(t / 5.7 + p) * .5 + Math.sin(t / 2.2 + p * 1.7) * .3 + Math.sin(t / 11.3 + p * 2.1) * .2;
  const factor = 1 + wave * vol + sentiment(t) * vol * .5 + tickJitter(card.id + finish, now) * vol;
  return Math.max(.55, Math.min(1.85, factor));
}
