Handler:
```js
const gradeBtn = el('[data-grade-item]');
if (gradeBtn) {
  const uid=..., sid=..., cardId=...
  const card = CARD_MAP[cardId]; const svc = GRADING_SERVICES.find(s=>s.id===sid);
  if (card && svc) {
    const fee = `${svc.currency==='gems'?'◆':'◈'} ${fmt(svc.cost)}`;
    confirmAction({
      title:`Grade ${card.name}?`,
      body:`${svc.company} ${svc.name} costs ${fee}. Grading is permanent. Most cards land 6–9; grade 8+ raises value, lower grades can reduce it.`,
      confirmText:`Grade · ${fee}`,
      onConfirm:()=>{
        try { const res=gradeItem(uid,sid); sfx.claim(); toast(...); closeModal(); setTimeout(()=>openCard(cardId, uid), 40); }
        catch(err){ sfx.error(); toast('red','Grading failed',err.message,'!'); }
      }
    });
  }
  return;
}
