function tickFactor(card, finish, now) {
  const bucket = Math.floor(now / 15000);
  const jitter = ((hash32(card.id + '|' + finish + '|' + bucket) % 2000) / 1000) - 1;
  const vol = (RARITY_VOL[card.rarity] || .085) * (FINISH_VOL[finish] || 1);
  return jitter * vol * .28;
}

