      wantItem: d.item,
      wantFinish: d.item.finish,
      wantValue: d.value,
      give: offerCard,
      giveValue: offerValue,
      ratio,
      verdict: ratio >= 1.15 ? 'good' : ratio >= .82 ? 'fair' : 'bad',
    });
  }
