238:   const remove = [];
239:   for (const g of groups) {
240:     if (filterFn && !filterFn(g.card)) continue;
241:     if (g.items.length <= 1) continue;
242:     // keep the most valuable copy, sell the rest
243:     const sorted = [...g.items].sort((a,b) => itemMarketValue(b) - itemMarketValue(a));
244:     for (const item of sorted.slice(1)) {
245:       total += itemMarketValue(item);
246:       count++;
247:       remove.push(item.uid);
248:     }
249:   }
250:   if (!count) return {count:0, total:0};
251:   state.items = state.items.filter(i => !remove.includes(i.uid));
252:   state.coins += total;
253:   state.stats.cardsSold += count;
254:   state.stats.coinsEarned += total;
255:   state.daily.cardsSold += count;
256:   addXp(count * 3);
257:   save(); emit();
258:   return {count, total};
