284: function rngFrom(seed) {
285:   let a = seed >>> 0;
286:   return () => { a |= 0; a = a + 0x6D2B79F5 | 0; let t = Math.imul(a ^ a >>> 15, 1 | a); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; };
287: }
288: function weighted(entries, rnd = Math.random) {
289:   const total = entries.reduce((s,e) => s + e[1], 0);
290:   if (total <= 0) return entries[0]?.[0];
291:   let r = rnd() * total;
292:   for (const [key, w] of entries) { r -= w; if (r <= 0) return key; }
293:   return entries[entries.length-1][0];
294: }
295: function packPool(pack) {
296:   let pool = CARDS;
297:   if (pack.scope === 'f1') pool = pool.filter(c => c.sport === 'f1');
298:   else if (pack.scope === 'motogp') pool = pool.filter(c => c.sport === 'motogp');
299:   else if (pack.scope === 'crossover') pool = pool;
300:   else pool = pool.filter(c => c.sport !== 'crossover');
301:   const f = pack.pool || {};
302:   if (f.sport) pool = pool.filter(c => c.sport === f.sport);
303:   if (f.types) pool = pool.filter(c => f.types.includes(c.type));
304:   if (f.eras) pool = pool.filter(c => f.eras.includes(c.era));
305:   if (f.countries) pool = pool.filter(c => f.countries.includes(c.country));
306:   if (f.teams) pool = pool.filter(c => f.teams.includes(c.team));
307:   if (f.ids) { const set = new Set(f.ids); pool = pool.filter(c => set.has(c.id)); }
308:   if (f.signatures) pool = pool.filter(c => !!c.signature);
309:   if (f.query) pool = pool.filter(c => c.searchable.includes(f.query));
310:   return pool.length ? pool : CARDS;
311: }
312: function rollRarity(pack, rnd) {
313:   const base = {...pack.odds};
314:   // Reworked odds: top tiers are significantly harder to hit. Removed
315:   // weight is pushed into the lowest available tier so pack totals stay 100.
316:   const cuts = {epic: .78, legendary: .42, iconic: .3};
317:   let removed = 0;
318:   for (const k of ['epic','legendary','iconic']) {
319:     const before = base[k] || 0;
320:     base[k] = before * cuts[k];
321:     removed += before - base[k];
322:   }
323:   const sink = base.common > 0 ? 'common' : (base.rare > 0 ? 'rare' : (base.epic > 0 ? 'epic' : 'legendary'));
324:   base[sink] = (base[sink] || 0) + removed;
325:   return weighted(Object.entries(base).map(([k,v]) => [k, v]), rnd);
326: }
327: function cardOfRarity(pool, rarity, exclude, unownedOnly, owned, rnd) {
328:   let candidates = pool.filter(c => c.rarity === rarity && !exclude.has(c.id) && (!unownedOnly || !owned.has(c.id)));
329:   if (!candidates.length) {
330:     const order = ['common','rare','epic','legendary','iconic'];
331:     const start = order.indexOf(rarity);
332:     for (let d = 1; d < order.length && !candidates.length; d++) {
333:       for (const idx of [start-d, start+d]) {
334:         if (idx < 0 || idx >= order.length) continue;
335:         candidates = pool.filter(c => c.rarity === order[idx] && !exclude.has(c.id) && (!unownedOnly || !owned.has(c.id)));
336:         if (candidates.length) break;
337:       }
338:     }
339:   }
340:   if (!candidates.length) return null;
341:   return candidates[Math.floor(rnd() * candidates.length)];
342: }
343: function rollFinish(pack, card, rnd) {
344:   const weights = finishWeights(pack, card);
345:   const entries = Object.entries(weights).filter(([k,w]) => w > 0 && (k !== 'signature' || !!card.signature));
346:   return weighted(entries, rnd);
347: }
348: function serialFor(card) {
349:   const max = card.rarity === 'iconic' ? 25 : card.rarity === 'legendary' ? 50 : 99;
350:   return Math.floor(Math.random() * max) + 1;
351: }
