353: function generatePull(pack, forcedFinish = null) {
354:   const pool = packPool(pack);
355:   const rnd = Math.random;
356:   const owned = new Set(state.items.map(i => i.cardId));
357:   const picks = [];
358:   const used = new Set();
359:   const floors = pack.guarantees || {};
360:   const cardCount = pack.cards;
361:   const protectedNew = Math.max(pack.guaranteeNew || 0, pack.protectDupes || 0);
362:   const allFloor = Object.entries(floors).reduce((best, [rar, n]) => (n >= cardCount && RANK[rar] > RANK[best] ? rar : best), 'common');
363: 
364:   for (let slot = 0; slot < cardCount; slot++) {
365:     let rarity;
366:     if (slot < protectedNew && owned.size < 420) {
367:       rarity = rollRarity(pack, rnd);
368:       let card = cardOfRarity(pool, rarity, used, true, owned, rnd);
369:       if (!card) card = cardOfRarity(pool, rarity, used, false, owned, rnd);
370:       if (card) {
371:         picks.push({card, new: !owned.has(card.id)});
372:         used.add(card.id);
373:         continue;
374:       }
375:     }
376:     rarity = rollRarity(pack, rnd);
377:     if (RANK[rarity] < RANK[allFloor]) rarity = allFloor;
378:     let card = cardOfRarity(pool, rarity, used, false, owned, rnd);
379:     if (!card) card = cardOfRarity(pool, rarity, used, false, owned, rnd);
380:     if (!card) card = pool.find(c => !used.has(c.id)) || pool[0];
381:     picks.push({card, new: !owned.has(card.id)});
382:     used.add(card.id);
383:   }
384: 
385:   // rarity floor guarantees
386:   for (const [rar, need] of Object.entries(floors)) {
387:     let have = picks.filter(p => RANK[p.card.rarity] >= RANK[rar]).length;
388:     while (have < need) {
389:       const target = picks.reduce((low, p, idx) => (RANK[p.card.rarity] < RANK[picks[low].card.rarity] ? idx : low), 0);
390:       const exclude = new Set(picks.filter((_,i)=>i!==target).map(p => p.card.id));
391:       let card = cardOfRarity(pool, rar, exclude, true, owned, rnd);
392:       if (!card) {
393:         // find any card at or above rarity
394:         const order = ['common','rare','epic','legendary','iconic'];
395:         for (let r = RANK[rar]; r <= 4 && !card; r++) card = cardOfRarity(pool, order[r], exclude, false, owned, rnd);
396:       }
397:       if (!card) break;
398:       picks[target] = {card, new: !owned.has(card.id)};
399:       have = picks.filter(p => RANK[p.card.rarity] >= RANK[rar]).length;
400:     }
401:   }
402: 
403:   // guarantee new cards / duplicate protection remaining
404:   let newCount = picks.filter(p => p.new).length;
405:   for (let i = 0; i < picks.length && newCount < protectedNew; i++) {
406:     if (picks[i].new) continue;
407:     const exclude = new Set(picks.map(p => p.card.id));
408:     let card = cardOfRarity(pool, picks[i].card.rarity, exclude, true, owned, rnd);
409:     if (!card && RANK[allFloor] > 0) card = cardOfRarity(pool, allFloor, exclude, true, owned, rnd);
410:     if (card) { picks[i] = {card, new: true}; newCount++; }
411:   }
412: 
413:   // crossover guarantee
414:   if (pack.scope === 'crossover') {
415:     const hasX = picks.some(p => p.card.sport === 'crossover');
416:     if (!hasX) {
417:       const xPool = CARDS.filter(c => c.sport === 'crossover');
418:       const xCard = xPool[Math.floor(rnd() * xPool.length)];
419:       const idx = picks.reduce((low, p, i) => RANK[p.card.rarity] < RANK[picks[low].card.rarity] ? i : low, 0);
420:       picks[idx] = {card: xCard, new: !owned.has(xCard.id)};
421:     }
422:   }
423: 
424:   let result = picks.map(p => {
425:     let finish = rollFinish(pack, p.card, rnd);
426:     if (finish === 'base' && forcedFinish) finish = forcedFinish;
427:     return {card: p.card, finish, isNew: p.new, serial: null};
428:   });
429:   if (pack.guaranteedFinish) {
430:     // The advertised finish is guaranteed on the best card in the pack only.
431:     const idx = result.reduce((best, r, i) => RANK[r.card.rarity] > RANK[result[best].card.rarity] ? i : best, 0);
432:     result[idx].finish = pack.guaranteedFinish;
433:   }
434:   for (const r of result) {
435:     if (r.finish === 'numbered') r.serial = serialFor(r.card);
436:   }
437:   return result;
438: }
