440: export function openPack(packId, opts = {}) {
441:   ensureToday();
442:   const today = todayKey();
443:   let pack;
444:   if (packId === 'potd') {
445:     pack = getPackOfTheDay(new Date());
446:     if (state.potd.purchases >= 3) throw gameError('POTD_LIMIT', 'Daily limit reached for Pack of the Day');
447:   } else {
448:     pack = PACK_MAP[packId];
449:   }
450:   if (!pack) throw gameError('NO_PACK', 'Unknown pack');
451: 
452:   let deal = null;
453:   if (opts.deal && opts.deal.baseId === (pack.baseId || pack.id) && opts.deal.endsAt > Date.now()) {
454:     deal = opts.deal;
455:     pack = {
456:       ...pack,
457:       name: deal.name || pack.name,
458:       cost: deal.cost,
459:       baseCost: deal.baseCost,
460:       discount: deal.discount,
461:       deal: true,
462:       extra: deal.extra,
463:       bonusCards: deal.bonusCards || 0,
464:       endsAt: deal.endsAt,
465:     };
466:   }
467: 
468:   const availability = packAvailability(pack);
469:   if (!availability.available) throw gameError('PACK_LOCKED', `${pack.name} is not live right now`);
470:   if (pack.oncePerDay && state.dailyPackDate === today) throw gameError('DAILY_USED', 'Daily Pack already claimed today');
471:   if (packId === 'potd' && state.coins < pack.cost && !state.tokens.includes('potd')) {
472:     throw gameError('NOT_ENOUGH_COINS', 'Not enough coins');
473:   }
474: 
475:   let usedToken = false;
476:   const tokenIdx = state.tokens.indexOf(packId);
477:   if (tokenIdx >= 0 && packId !== 'potd' && !deal) {
478:     state.tokens.splice(tokenIdx, 1);
479:     usedToken = true;
480:     state.tokensUsed++;
481:   } else {
482:     spendCurrency(pack.currency, pack.cost);
483:   }
484: 
485:   const pullPack = pack.bonusCards ? {...pack, cards: pack.cards + pack.bonusCards} : pack;
486:   const pulls = generatePull(pullPack);
487:   const results = [];
488:   for (const p of pulls) {
489:     const item = addItem(p.card.id, p.finish, {serial: p.serial, source: packId});
490:     const value = marketValue(p.card, p.finish);
491:     results.push({...p, item, value});
492:     state.stats.cardsPulled++;
493:     if (p.isNew) { state.daily.newCards++; }
494:     if (RANK[p.card.rarity] >= 2) state.stats.epicPulls++;
495:     if (RANK[p.card.rarity] >= 2) state.daily.epicPulls++;
496:     if (RANK[p.card.rarity] >= 3) { state.stats.legendaryPulls++; state.daily.legendaryPulls++; }
497:     if (RANK[p.card.rarity] >= 4) state.stats.iconicPulls++;
498:     state.recentPulls.unshift({cardId: p.card.id, finish: p.finish, serial: p.serial, isNew: p.isNew, at: Date.now(), uid: item.uid});
499:   }
500:   state.recentPulls = state.recentPulls.slice(0, 24);
501:   state.stats.packsOpened++;
502:   state.daily.packsOpened++;
503:   if (pack.oncePerDay) state.dailyPackDate = today;
504:   if (packId === 'daily') { state.stats.dailyPacks++; state.daily.dailyPacks++; }
505:   if (packId === 'gold' || packId === 'f1-gold' || packId === 'motogp-gold') { state.stats.goldPacks++; state.daily.goldPacks++; }
506:   if (pack.category === 'event') state.stats.eventPacks = (state.stats.eventPacks || 0) + 1;
507:   if (deal) state.stats.offerPacks = (state.stats.offerPacks || 0) + 1;
508:   if (packId === 'potd') state.potd.purchases++;
509: 
510:   /* Choice packs: build the option table after the normal pulls land. */
511:   let choice = null;
512:   if (pack.choice) {
513:     const cfg = pack.choice;
514:     const pool = packPool(pack);
515:     const ownedNow = new Set(state.items.map(i => i.cardId));
516:     const used = new Set(results.map(r => r.card.id));
517:     const options = [];
518:     for (let i = 0; i < (cfg.count || 3); i++) {
519:       const rarity = cfg.rarity || 'legendary';
520:       let card = cardOfRarity(pool, rarity, used, true, ownedNow, Math.random)
521:         || cardOfRarity(pool, rarity, used, false, ownedNow, Math.random);
522:       if (!card) card = pool.find(c => !used.has(c.id)) || pool[i % pool.length];
523:       let finish = rollFinish(pack, card, Math.random);
524:       if (finish === 'base' && cfg.finish) finish = cfg.finish;
525:       options.push({card, finish, serial: null, isNew: !ownedNow.has(card.id)});
526:       used.add(card.id);
527:     }
528:     for (const o of options) if (o.finish === 'numbered') o.serial = serialFor(o.card);
529:     choice = {options, picks: cfg.picks || 1, chosenCount: 0, chosen: null};
530:   }
531: 
532:   const xpGain = 30 + results.reduce((s, r) => s + (r.isNew ? 12 : 2) + ({common:0,rare:2,epic:8,legendary:18,iconic:45}[r.card.rarity] || 0), 0);
533:   const levelUps = addXp(xpGain);
534:   if (state.stats.maxUnique < uniqueCount()) state.stats.maxUnique = uniqueCount();
535:   save(); emit();
536:   return {pack, results, choice, usedToken, currency: pack.currency, amount: pack.cost, levelUps, xpGain, deal};
537: }
