539: export function choosePackCard(result, cardId) {
540:   const choice = result?.choice;
541:   if (!choice) throw gameError('NO_CHOICE', 'This pack has no choice to make');
542:   if (choice.chosenCount >= choice.picks) throw gameError('CHOICE_DONE', 'You have already made your pick');
543:   const option = choice.options.find(o => o.card.id === cardId && !o.taken);
544:   if (!option) throw gameError('NO_OPTION', 'That card is not one of the choices');
545:   const item = addItem(option.card.id, option.finish, {serial: option.serial, source:'choice'});
546:   const value = marketValue(option.card, option.finish);
547:   option.taken = true;
548:   option.item = item;
549:   option.value = value;
550:   choice.chosenCount++;
551:   if (choice.chosenCount >= choice.picks) choice.chosen = option;
552: 
553:   state.stats.cardsPulled++;
554:   state.daily.newCards += option.isNew ? 1 : 0;
555:   if (RANK[option.card.rarity] >= 2) { state.stats.epicPulls++; state.daily.epicPulls++; }
556:   if (RANK[option.card.rarity] >= 3) { state.stats.legendaryPulls++; state.daily.legendaryPulls++; }
557:   if (RANK[option.card.rarity] >= 4) state.stats.iconicPulls++;
558:   state.recentPulls.unshift({cardId: option.card.id, finish: option.finish, serial: option.serial, isNew: option.isNew, at: Date.now(), uid: item.uid});
559:   state.recentPulls = state.recentPulls.slice(0, 24);
560:   addXp(18);
561:   if (state.stats.maxUnique < uniqueCount()) state.stats.maxUnique = uniqueCount();
562:   save(); emit();
563:   return {option, item, value};
564: }
