800:   const dupes = [];
801:   for (const g of groups) {
802:     // Offer the lowest-value spare copy in a trade.
803:     const copies = [...g.items].sort((a,b) => itemMarketValue(b) - itemMarketValue(a));
804:     const spare = copies[copies.length - 1];
805:     dupes.push({group: g, item: spare, value: itemMarketValue(spare)});
806:   }
807:   const owned = new Set(state.items.map(i => i.cardId));
808:   const offeredIds = new Set();
809:   const usedDupes = new Set();
810:   for (let i = 0; i < 4 && dupes.length; i++) {
811:     const d = dupes[Math.floor(rnd() * dupes.length)];
812:     if (!d || usedDupes.has(d.item.uid)) continue;
813:     usedDupes.add(d.item.uid);
814:     const wantRank = RANK[d.group.card.rarity];
815:     const bump = rnd() > .8 ? 1 : 0;
816:     const targetRank = Math.min(4, wantRank + bump);
817:     const rarities = ['common','rare','epic','legendary','iconic'];
818:     let candidates = CARDS.filter(c => !owned.has(c.id) && !offeredIds.has(c.id) && RANK[c.rarity] === targetRank);
819:     if (!candidates.length) candidates = CARDS.filter(c => !owned.has(c.id) && !offeredIds.has(c.id) && Math.abs(RANK[c.rarity] - wantRank) <= 1);
820:     if (!candidates.length) candidates = CARDS.filter(c => !owned.has(c.id) && !offeredIds.has(c.id));
821:     if (!candidates.length) break;
822:     const offerCard = candidates[Math.floor(rnd() * candidates.length)];
823:     offeredIds.add(offerCard.id);
824:     const offerValue = marketValue(offerCard, 'base');
825:     const ratio = offerValue / Math.max(1, d.value);
826:     offers.push({
827:       id: `t${state.tradeSeed}_${i}`,
828:       trader: TRADERS[(state.tradeSeed + i) % TRADERS.length],
829:       want: d.group.card,
830:       wantItem: d.item,
831:       wantFinish: d.item.finish,
832:       wantValue: d.value,
833:       give: offerCard,
