509: /* ------------------------------------------------------------
510:    FX CANVAS
511:    ------------------------------------------------------------ */
512: let fxCanvas = null;
513: let fxCtx = null;
514: let particles = [];
515: let fxRaf = 0;
516: export function initFx() {
517:   fxCanvas = document.getElementById('fx');
518:   if (!fxCanvas) return;
519:   fxCtx = fxCanvas.getContext('2d');
520:   resizeFx();
521:   window.addEventListener('resize', resizeFx);
522:   document.addEventListener('pointermove', ev => {
523:     const card = ev.target.closest?.('.card');
524:     if (!card) return;
525:     const r = card.getBoundingClientRect();
526:     if (!r.width || !r.height) return;
527:     card.style.setProperty('--mx', `${((ev.clientX - r.left) / r.width * 100).toFixed(1)}%`);
528:     card.style.setProperty('--my', `${((ev.clientY - r.top) / r.height * 100).toFixed(1)}%`);
529:   }, {passive: true});
530: }
531: function resizeFx() {
532:   if (!fxCanvas) return;
533:   const dpr = Math.min(2, window.devicePixelRatio || 1);
534:   fxCanvas.width = Math.floor(innerWidth * dpr);
535:   fxCanvas.height = Math.floor(innerHeight * dpr);
536:   fxCanvas.style.width = innerWidth + 'px';
537:   fxCanvas.style.height = innerHeight + 'px';
538:   if (fxCtx) fxCtx.setTransform(dpr, 0, 0, dpr, 0, 0);
539: }
540: export function burst(color = '#ffc247', amount = 80, power = 1) {
541:   if (!fxCtx) return;
542:   const cx = innerWidth / 2, cy = innerHeight * 0.46;
543:   const palette = color === 'iconic'
544:     ? ['#ff66d8', '#ffe27a', '#65ffc8', '#5ad0ff', '#b17dff']
545:     : color === 'legendary'
546:       ? ['#ffc247', '#ffe8a8', '#ff9b30', '#ffffff']
547:       : [color, '#ffffff', '#ffd166'];
548:   for (let i = 0; i < amount; i++) {
549:     const ang = Math.random() * Math.PI * 2;
550:     const sp = (2.5 + Math.random() * 8) * power;
551:     particles.push({
552:       x: cx, y: cy,
553:       vx: Math.cos(ang) * sp,
554:       vy: Math.sin(ang) * sp - 2,
555:       size: 2 + Math.random() * 5,
556:       life: 1,
557:       decay: .008 + Math.random() * .012,
558:       color: palette[Math.floor(Math.random() * palette.length)],
559:       rot: Math.random() * 6,
560:       vr: (Math.random() - .5) * .3,
561:       shape: Math.random() > .55 ? 'line' : 'rect',
562:     });
563:   }
564:   if (!fxRaf) fxRaf = requestAnimationFrame(drawFx);
565: }
566: function drawFx() {
567:   if (!fxCtx) return;
568:   fxCtx.clearRect(0, 0, innerWidth, innerHeight);
569:   particles = particles.filter(p => p.life > 0);
570:   for (const p of particles) {
571:     p.x += p.vx; p.y += p.vy;
572:     p.vy += .13; p.vx *= .994; p.vy *= .994;
573:     p.life -= p.decay;
574:     p.rot += p.vr;
575:     fxCtx.save();
576:     fxCtx.globalAlpha = Math.max(0, p.life);
577:     fxCtx.fillStyle = p.color;
578:     fxCtx.translate(p.x, p.y);
579:     fxCtx.rotate(p.rot);
