53:     <div class="op-pack-nameplate"><b>${esc(pack.name)}</b><span>·</span>${pack.cards} cards<span>·</span>${esc(pack.currency === 'gems' ? `◆ ${fmt(pack.cost)}` : pack.cost === 0 ? 'FREE' : `◈ ${fmt(pack.cost)}`)}</div>
54:     <div class="op-pack-specs">${specs.map(s => `<span>${esc(s)}</span>`).join('')}</div>
