78: function reveal() {
79:   if (!op) return;
80:   const { results } = op.result;
81:   if (op.idx >= results.length) return finishReveal();
82:   const r = results[op.idx];
83:   const rank = RARITY[r.card.rarity].rank;
84:   const wantsWalkout = (rank >= 3 && !op.walked.has('legendary')) || rank >= 4;
85:   if (wantsWalkout) {
86:     op.walked.add(rank >= 4 ? 'iconic' : 'legendary');
87:     walkout(r, () => drawReveal(r));
88:   } else {
89:     drawReveal(r);
