219:     </div>
220:     <div class="choice-grid">
221:       ${opts.map((o, i) => `<button class="choice-opt${o.taken ? ' taken' : ''}" data-choice-id="${esc(o.card.id)}" ${o.taken ? 'disabled' : ''} style="--i:${i}">
222:         <div class="choice-card">${cardHTML(o.card, { finish: o.finish, serial: o.serial, isNew: o.isNew })}</div>
223:         <div class="choice-meta">
