225:           <span>${esc(o.card.sport === 'motogp' ? 'MotoGP' : o.card.sport === 'crossover' ? 'Crossover' : 'Formula 1')} · ${esc(o.card.typeLabel)} · ${esc(finishName(o.finish))}</span>
226:           ${o.isNew ? '<span class="new-pill">NEW TO VAULT</span>' : '<span class="dupe-pill">DUPLICATE · ◈ ' + fmt(marketValue(o.card, o.finish)) + '</span>'}
227:         </div>
228:       </button>`).join('')}
229:     </div>
230:     <div class="choice-note">${remaining} of ${choice.picks} picks remaining · ${opts.filter(o => !o.taken).length} option${opts.filter(o => !o.taken).length === 1 ? '' : 's'} left</div>
231:   </div>`;
232:   stage.querySelectorAll('[data-choice-id]').forEach(btn => {
233:     if (btn.disabled) return;
