238:         sfx.claim();
239:         if (res?.option) {
240:           op.result.choice.chosen = { card: res.option.card, finish: res.option.finish, serial: res.option.serial, isNew: res.option.isNew, value: res.value, item: res.item };
241:           op.result.choice.chosenCount = op.result.choice.chosenCount;
242:         }
243:         if (op.result.choice.chosenCount < op.result.choice.picks) choiceStage();
244:         else finishReveal();
