266: function updateDots(allDone = false) {
267:   if (!op) return;
268:   const dots = op.el.querySelectorAll('[data-dot]');
269:   dots.forEach((dot, i) => {
270:     dot.className = 'op-dot';
271:     const r = op.result.results[i];
272:     if (allDone || i < op.idx) {
273:       dot.classList.add('done');
274:       if (r?.card.rarity === 'legendary') dot.classList.add('pulled-legendary');
275:       if (r?.card.rarity === 'iconic') dot.classList.add('pulled-iconic');
276:     } else if (i === op.idx && op.phase !== 'walkout') {
277:       dot.classList.add('now');
278:     }
279:   });
