282: function bind() {
283:   op.el.querySelector('[data-op-skip]').addEventListener('click', () => {
284:     if (!op) return;
285:     sfx.tab();
286:     if (op.phase === 'pack' || op.phase === 'tear') {
287:       op.el.classList.add('tearing');
288:       clearTimers();
289:       op.phase = 'reveal';
290:       op.idx = 0;
291:       reveal();
292:     } else if (op.phase === 'walkout') {
293:       clearTimers();
294:       reveal();
295:     } else if (op.phase === 'reveal') {
296:       finishReveal();
297:     }
298:   });
299:   op.keyHandler = ev => {
300:     if (!op) return;
301:     if (document.querySelector('.modal-backdrop')) return;
302:     if (ev.key === 'Escape') { closeOpening(); }
303:     if (ev.key === ' ' || ev.key === 'Enter') {
304:       if (op.phase === 'pack') { ev.preventDefault(); tear(); }
305:       else if (op.phase === 'reveal') { ev.preventDefault(); next(); }
306:     }
307:   };
308:   window.addEventListener('keydown', op.keyHandler);
309: }
310: 
311: function later(fn, ms) {
312:   if (!op) return;
313:   const t = setTimeout(() => { op && (op.timers = op.timers.filter(x => x !== t)); fn(); }, ms);
314:   op.timers.push(t);
315: }
316: function clearTimers() {
317:   if (!op) return;
318:   op.timers.forEach(clearTimeout);
319:   op.timers = [];
320: }
321: 
322: export function closeOpening(notify = true) {
323:   if (!op) return;
324:   clearTimers();
325:   if (op.keyHandler) window.removeEventListener('keydown', op.keyHandler);
326:   op.el.remove();
327:   document.body.classList.remove('no-scroll');
328:   const cb = op.onClose;
329:   op = null;
330:   if (notify && cb) cb();
331: }
332: export function isOpening() { return !!op; }

