30: function tone(freq, dur, opts = {}) {
31:   const c = ensure(); if (!c) return;
32:   const { type = 'sine', gain = .12, slide = null, delay = 0, attack = .005, release = dur } = opts;
33:   const t0 = c.currentTime + delay;
34:   const osc = c.createOscillator();
35:   const g = c.createGain();
36:   osc.type = type;
37:   osc.frequency.setValueAtTime(freq, t0);
38:   if (slide != null) osc.frequency.exponentialRampToValueAtTime(Math.max(20, slide), t0 + dur);
39:   g.gain.setValueAtTime(0.0001, t0);
40:   g.gain.exponentialRampToValueAtTime(gain, t0 + attack);
41:   g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur + release * .4);
42:   osc.connect(g); g.connect(master);
43:   osc.start(t0); osc.stop(t0 + dur + release + .1);
44: }
45: 
46: function noise(dur, opts = {}) {
47:   const c = ensure(); if (!c) return;
48:   const { gain = .1, filter = 1200, q = 1, delay = 0, slideTo = null, type = 'bandpass' } = opts;
49:   if (!noiseBuf) {
50:     noiseBuf = c.createBuffer(1, c.sampleRate * 2, c.sampleRate);
51:     const data = noiseBuf.getChannelData(0);
52:     for (let i = 0; i < data.length; i++) data[i] = Math.random() * 2 - 1;
53:   }
54:   const t0 = c.currentTime + delay;
55:   const src = c.createBufferSource();
56:   src.buffer = noiseBuf;
57:   const f = c.createBiquadFilter();
58:   f.type = type;
59:   f.frequency.setValueAtTime(filter, t0);
60:   if (slideTo) f.frequency.exponentialRampToValueAtTime(slideTo, t0 + dur);
61:   f.Q.value = q;
62:   const g = c.createGain();
63:   g.gain.setValueAtTime(0.0001, t0);
64:   g.gain.exponentialRampToValueAtTime(gain, t0 + .01);
65:   g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
66:   src.connect(f); f.connect(g); g.connect(master);
67:   src.start(t0); src.stop(t0 + dur + .05);
68: }
69: 
70: function rev(base = 70, dur = 1.1, gain = .2, delay = 0) {
71:   const c = ensure(); if (!c) return;
72:   const t0 = c.currentTime + delay;
73:   // layered saw engine
74:   for (let i = 0; i < 3; i++) {
75:     const osc = c.createOscillator();
76:     const g = c.createGain();
77:     const f = c.createBiquadFilter();
78:     osc.type = i === 0 ? 'sawtooth' : 'square';
79:     const start = base + i * 2.5;
80:     osc.frequency.setValueAtTime(start, t0);
81:     osc.frequency.exponentialRampToValueAtTime(start * 2.1, t0 + dur * .45);
82:     osc.frequency.exponentialRampToValueAtTime(start * 1.15, t0 + dur);
83:     f.type = 'lowpass';
84:     f.frequency.setValueAtTime(500 + i * 200, t0);
85:     f.frequency.exponentialRampToValueAtTime(2600, t0 + dur * .4);
86:     f.frequency.exponentialRampToValueAtTime(700, t0 + dur);
87:     f.Q.value = 3;
88:     g.gain.setValueAtTime(0.0001, t0);
89:     g.gain.exponentialRampToValueAtTime(gain / (i + 1.4), t0 + .06);
90:     g.gain.exponentialRampToValueAtTime(gain * .35, t0 + dur * .6);
91:     g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
92:     osc.connect(f); f.connect(g); g.connect(master);
93:     osc.start(t0); osc.stop(t0 + dur + .1);
94:   }
95:   noise(dur * .8, {gain: gain * .22, filter: 300, slideTo: 1800, q: .6, delay, type: 'lowpass'});
96: }
