98: function chord(freqs, dur, gain = .08, type = 'triangle', delay = 0) {
99:   freqs.forEach((f, i) => tone(f, dur, {type, gain: gain / (1 + i * .25), delay: delay + i * .035, attack: .02}));
100: }
