Need export functions for vault screen. Add after potdPurchasesLeft or near end. Let's add a section before misc maybe after market. We'll insert after `refreshMarket` perhaps. Need functions:
- `vaultEditions()` returns edition info with supply/issued/owned.
- `vaultOverview()` returns totals & exclusives.
- `redeemVault(editionId)`.

Also `redeemVault` must be careful: AUTOGRAPH_SPECS cards per edition 10 legends; one-of-one supply 1 each, total 10 one-of-one cards (one per legend). Editions supply per card. For display total supply = supply * #cards.

Implementation:
```
export function vaultEditions() {
  return AUTOGRAPH_EDITIONS.map(ed => {
    const cards = AUTOGRAPH_SPECS.filter(s=>s.editionId===ed.id).map(s=>AUTOGRAPH_MAP[s.id]).filter(Boolean);
    const issued = cards.reduce((n,c)=>n+supplyInfo(c,c.finish).issued,0);
    const owned = state.items.filter(i=>cards.some(c=>c.id===i.cardId)).length;
    return {...ed, cards, cardCount: cards.length, cap: ed.supply*cards.length, issued, remaining:..., owned, purchasable: ed.tokens!=null};
  });
}
export function vaultCollectibles() { // exclusives grouped by edition
  return EXCLUSIVE_CARDS.map(c=>({card:c, ...supplyInfo(c,c.finish)}));
}
export function redeemVault(editionId) {
  const ed = AUTOGRAPH_EDITIONS.find...
  if (!ed) throw...
  if (ed.tokens == null) throw gameError('NOT_FOR_SALE', 'One-of-One cards cannot be redeemed with tokens')
  if (state.collectorTokens < ed.tokens) throw NOT_ENOUGH_TOKENS
  const candidates = ... filter supply
  if none throw SOLD_OUT
  const card = candidates[Math.floor(Math.random()*...)]
  // deduct tokens only after supply check; addItem may throw but then tokens should refund.
  try {
    const item = addItem(card.id, card.finish, {source:'vault'});
    state.collectorTokens -= ed.tokens;
    state.vault.redeemed.unshift({cardId, editionId, at, serial});
    state.vault.opened++;
    state.stats.vaultRedeems++;
    addXp(70);
    save(); emit();
    return {card, item, cost:ed.tokens, edition:ed};
  } catch(e) { throw e; }
}
