/* ---- grading slab badge ---- */
.card-grade{position:absolute;top:3.1cqw;left:50%;transform:translateX(-50%);z-index:7;display:flex;flex-direction:column;align-items:center;line-height:.82;padding:.55cqw 1.35cqw .5cqw;border-radius:.7cqw;background:linear-gradient(180deg,rgba(5,7,10,.94),rgba(5,7,10,.7));border:.45px solid color-mix(in srgb,var(--gc,#f6c453) 62%, transparent);box-shadow:0 0 14px color-mix(in srgb,var(--gc,#f6c453) 28%, transparent), inset 0 1px 0 rgba(255,255,255,.18);backdrop-filter:blur(5px)}
