.card.graded .card-frame{background:linear-gradient(155deg,rgba(255,255,255,.7),color-mix(in srgb,var(--gc,#f6c453) 45%, transparent) 28%,rgba(255,255,255,.05) 58%,rgba(255,255,255,.45));opacity:.8}
.card.graded::after{background:linear-gradient(115deg,rgba(255,255,255,.22) 0%,transparent 10%,transparent 86%,rgba(255,255,255,.14) 94%,transparent 100%),linear-gradient(180deg,transparent 70%,color-mix(in srgb,var(--gc,#f6c453) 8%, transparent) 100%);opacity:.8}
