.vi-emblem{width:58px;height:58px;display:grid;place-items:center;border-radius:16px;font-size:28px;color:#f4e9ff;background:radial-gradient(circle at 35% 25%,rgba(228,194,255,.35),rgba(228,194,255,.06));border:1px solid rgba(228,194,255,.35);box-shadow:0 0 26px -8px rgba(228,194,255,.5)}
.vault-intro b{display:block;font-family:var(--font-display);font-size:20px;letter-spacing:.02em;margin-bottom:4px}
.vault-intro p{margin:0;color:var(--muted);font-size:12.5px;line-height:1.65;max-width:760px}
.vi-stats{display:flex;gap:16px;flex-wrap:wrap}
.vi-stats span{display:flex;flex-direction:column;align-items:flex-end;font-family:var(--font-tech);font-size:10px;letter-spacing:.12em;text-transform:uppercase;color:var(--muted)}
.vi-stats b{font-size:22px;color:var(--text)}

.vault-editions{display:grid;grid-template-columns:repeat(auto-fill,minmax(270px,1fr));gap:14px}
.vault-edition{position:relative;overflow:hidden;padding:18px;border-radius:15px;border:1px solid color-mix(in srgb,var(--ve,#e4c2ff) 26%, rgba(255,255,255,.06));background:linear-gradient(150deg,color-mix(in srgb,var(--ve,#e4c2ff) 10%, rgba(10,12,18,.9)),rgba(10,12,18,.96) 65%)}
.vault-edition::before{content:'';position:absolute;inset:-40% -30% auto auto;width:220px;height:220px;border-radius:50%;background:radial-gradient(circle,var(--ve-glow,rgba(228,194,255,.4)),transparent 68%);pointer-events:none}
.ve-top{display:flex;justify-content:space-between;align-items:center;gap:8px;position:relative;z-index:1}
.ve-short{font-family:var(--font-tech);font-weight:800;font-size:10px;letter-spacing:.2em;color:var(--ve,#e4c2ff)}
.ve-mult{font-family:var(--font-tech);font-size:10px;color:var(--muted)}
.vault-edition h3{position:relative;z-index:1;margin:8px 0 4px;font-family:var(--font-display);font-size:21px}
.ve-note{position:relative;z-index:1;margin:0 0 12px;color:var(--muted);font-size:11.5px;line-height:1.5;min-height:32px}
.ve-cards{position:relative;z-index:1;display:flex;gap:7px;margin-bottom:14px}
.ve-card{width:50px;height:70px;cursor:pointer;border-radius:7px;overflow:hidden;border:1px solid rgba(255,255,255,.12);transition:.2s}
.ve-card:hover{transform:translateY(-3px);border-color:var(--ve,#e4c2ff)}
.ve-card .mini-card{width:100%;height:100%}
.ve-supply{position:relative;z-index:1;margin-bottom:14px}
.ves-head,.ves-sub{display:flex;justify-content:space-between;gap:8px;font-family:var(--font-tech);font-size:10px;letter-spacing:.08em;color:var(--muted)}
.ves-head b{color:var(--text);font-size:12px}
.ves-track{height:5px;border-radius:5px;background:rgba(255,255,255,.08);overflow:hidden;margin:6px 0}
.ves-track i{display:block;height:100%;background:linear-gradient(90deg,var(--ve,#e4c2ff),var(--gold));box-shadow:0 0 10px var(--ve-glow,rgba(228,194,255,.5))}
.ve-foot{position:relative;z-index:1}
