.vault-cert{display:flex;flex-direction:column;gap:5px;padding:14px 16px;border:1px solid rgba(255,209,102,.24);border-radius:12px;background:linear-gradient(135deg,rgba(255,209,102,.07),rgba(10,12,18,.5));cursor:pointer;transition:.2s}
