.vc-serial{font-family:var(--font-tech);font-size:11px;color:#ffe6a6}
.vc-date{font-size:10px;color:var(--muted)}

.mh-list{display:grid;gap:4px;padding:10px}
.mh-row{display:grid;grid-template-columns:64px 34px minmax(120px,1fr) auto auto 70px;gap:10px;align-items:center;padding:7px 9px;border-radius:9px;background:rgba(255,255,255,.025);font-size:11px}
