.mh-type.sale{color:#ff9b52}
.mh-type.trade{color:#22d3ee}
.mh-card{width:30px;height:42px;overflow:hidden;border-radius:4px;border:1px solid rgba(255,255,255,.1)}
.mh-card .mini-card{width:100%;height:100%}
.mh-name{display:flex;flex-direction:column;gap:2px;min-width:0}
