.collectible-tag,.supply-pill{display:inline-block;margin-left:7px;padding:2px 6px;border-radius:5px;font-family:var(--font-tech);font-size:8px;letter-spacing:.1em;color:#ffd9f4;background:rgba(255,102,216,.14);border:1px solid rgba(255,102,216,.3)}
