.pd-exclusives{display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:8px}
.pd-exclusive{display:flex;flex-direction:column;gap:3px;padding:9px 11px;border-radius:9px;border:1px solid color-mix(in srgb,var(--ex,#ff66d8) 30%,rgba(255,255,255,.06));background:linear-gradient(135deg,color-mix(in srgb,var(--ex,#ff66d8) 10%,transparent),transparent)}
.pdex-edition{font-family:var(--font-tech);font-size:9px;letter-spacing:.14em;color:var(--ex,#ff66d8)}
.pd-exclusive b{font-size:12px}
.pdex-supply{font-size:10px;color:var(--muted)}
.pd-autograph-note p{font-size:11.5px;line-height:1.6;color:var(--muted);margin:0}

.walkout.grail .wo-big{background:linear-gradient(180deg,#fff,#ffd9f4 40%,#ff66d8);-webkit-background-clip:text;background-clip:text;color:transparent;filter:drop-shadow(0 0 14px rgba(255,102,216,.5))}
.walkout.grail .wo-kicker{color:#ffd9f4}
.walkout.grail .wo-cert{margin-top:10px;font-family:var(--font-tech);font-size:11px;letter-spacing:.1em;color:#ffe6a6;text-transform:uppercase}
.reveal-cert{display:block;margin-top:6px;font-family:var(--font-tech);font-size:9px;letter-spacing:.1em;color:#ffe6a6}

@media (max-width:900px){
  .vault-intro{grid-template-columns:auto 1fr}
  .vi-stats{grid-column:1/-1;justify-content:flex-start}
  .market-history{grid-template-columns:1fr}
  .vr-row{grid-template-columns:42px 1fr 90px;grid-template-areas:'card name supply' 'card edition bar'}
  .vr-card{grid-area:card}.vr-name{grid-area:name}.vr-edition{grid-area:edition}.vr-supply{grid-area:supply}.vr-bar{grid-area:bar}
  .mh-row{grid-template-columns:60px 34px 1fr auto}
  .mh-party,.mh-date{display:none}
}
@media (max-width:680px){
  .mobile-nav{overflow-x:auto;scrollbar-width:none}
  .mobile-nav::-webkit-scrollbar{display:none}
  .mobile-nav button{min-width:64px;flex:0 0 auto}
}

