21: /* Rarity is driven by the card rating so pack odds, collection filters and
22:    market values stay consistent with the printed OVR on every card. */
23: function rarityFor(overall) {
24:   if (overall >= 98) return 'iconic';
25:   if (overall >= 95) return 'legendary';
26:   if (overall >= 91) return 'epic';
27:   if (overall >= 86) return 'rare';
28:   return 'common';
29: }
30: 
31: function normalise(raw, sport, type) {
32:   const t = raw.type || type;
33:   const rarity = rarityFor(raw.ovr);
34:   const stat = {
35:     speed: raw.sp, skill: raw.sk, consistency: raw.co, racecraft: raw.rc,
36:   };
37:   const kit = kitFor(raw.t || raw.n);
