470: function generatePull(pack, forcedFinish = null) {
471:   const pool = packPool(pack);
472:   const rnd = Math.random;
473:   const owned = new Set(state.items.map(i => i.cardId));
474:   const picks = [];
475:   const used = new Set();
476:   const floors = pack.guarantees || {};
477:   const cardCount = pack.cards;
478:   const protectedNew = Math.max(pack.guaranteeNew || 0, pack.protectDupes || 0);
479:   const allFloor = Object.entries(floors).reduce((best, [rar, n]) => (n >= cardCount && RANK[rar] > RANK[best] ? rar : best), 'common');
480: 
481:   for (let slot = 0; slot < cardCount; slot++) {
482:     let rarity;
483:     if (slot < protectedNew && owned.size < 420) {
484:       rarity = rollRarity(pack, rnd);
485:       let card = cardOfRarity(pool, rarity, used, true, owned, rnd);
486:       if (!card) card = cardOfRarity(pool, rarity, used, false, owned, rnd);
487:       if (card) {
488:         picks.push({card, new: !owned.has(card.id)});
489:         used.add(card.id);
490:         continue;
491:       }
492:     }
493:     rarity = rollRarity(pack, rnd);
494:     if (RANK[rarity] < RANK[allFloor]) rarity = allFloor;
495:     let card = cardOfRarity(pool, rarity, used, false, owned, rnd);
496:     if (!card) card = cardOfRarity(pool, rarity, used, false, owned, rnd);
497:     if (!card) card = pool.find(c => !used.has(c.id)) || pool[0];
498:     picks.push({card, new: !owned.has(card.id)});
499:     used.add(card.id);
500:   }
501: 
502:   // rarity floor guarantees
503:   for (const [rar, need] of Object.entries(floors)) {
504:     let have = picks.filter(p => RANK[p.card.rarity] >= RANK[rar]).length;
505:     while (have < need) {
506:       const target = picks.reduce((low, p, idx) => (RANK[p.card.rarity] < RANK[picks[low].card.rarity] ? idx : low), 0);
507:       const exclude = new Set(picks.filter((_,i)=>i!==target).map(p => p.card.id));
508:       let card = cardOfRarity(pool, rar, exclude, true, owned, rnd);
509:       if (!card) {
510:         // find any card at or above rarity
511:         const order = ['common','rare','epic','legendary','iconic'];
512:         for (let r = RANK[rar]; r <= 4 && !card; r++) card = cardOfRarity(pool, order[r], exclude, false, owned, rnd);
513:       }
514:       if (!card) break;
515:       picks[target] = {card, new: !owned.has(card.id)};
516:       have = picks.filter(p => RANK[p.card.rarity] >= RANK[rar]).length;
517:     }
518:   }
519: 
520:   // guarantee new cards / duplicate protection remaining
521:   let newCount = picks.filter(p => p.new).length;
522:   for (let i = 0; i < picks.length && newCount < protectedNew; i++) {
523:     if (picks[i].new) continue;
524:     const exclude = new Set(picks.map(p => p.card.id));
525:     let card = cardOfRarity(pool, picks[i].card.rarity, exclude, true, owned, rnd);
526:     if (!card && RANK[allFloor] > 0) card = cardOfRarity(pool, allFloor, exclude, true, owned, rnd);
527:     if (card) { picks[i] = {card, new: true}; newCount++; }
528:   }
529: 
530:   // crossover guarantee
531:   if (pack.scope === 'crossover') {
532:     const hasX = picks.some(p => p.card.sport === 'crossover');
533:     if (!hasX) {
534:       const xPool = CARDS.filter(c => c.sport === 'crossover');
535:       const xCard = xPool[Math.floor(rnd() * xPool.length)];
536:       const idx = picks.reduce((low, p, i) => RANK[p.card.rarity] < RANK[picks[low].card.rarity] ? i : low, 0);
537:       picks[idx] = {card: xCard, new: !owned.has(xCard.id)};
538:     }
539:   }
540: 
541:   let result = picks.map(p => {
542:     let finish = rollFinish(pack, p.card, rnd);
543:     if (finish === 'base' && forcedFinish) finish = forcedFinish;
544:     return {card: p.card, finish, isNew: p.new, serial: null};
545:   });
546:   if (pack.guaranteedFinish) {
547:     // The advertised finish is guaranteed on the best card in the pack only.
548:     const idx = result.reduce((best, r, i) => RANK[r.card.rarity] > RANK[result[best].card.rarity] ? i : best, 0);
549:     result[idx].finish = pack.guaranteedFinish;
550:   }
551:   // Serial numbers are allocated by addItem from the permanent supply ledger,
552:   // never by the roller, so a sold-out run can never be issued again.
553:   return injectCollectibles(pack, result, owned);
554: }
