} from './pricing.js';

export const fmt = formatNumber;
export const FINISH_ORDER = ['base', 'holo', 'gold', 'championship', 'anniversary', 'signature', 'shadow', 'numbered'];

export function esc(value) {
  return String(value ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
