1024:     const offerCard = candidates[Math.floor(rnd() * candidates.length)];
1025:     offeredIds.add(offerCard.id);
1026:     const offerValue = marketValue(offerCard, 'base');
1027:     const ratio = offerValue / Math.max(1, d.value);
1028:     offers.push({
1029:       id: `t${state.tradeSeed}_${i}`,
1030:       trader: TRADERS[(state.tradeSeed + i) % TRADERS.length],
1031:       want: d.group.card,
1032:       wantItem: d.item,
1033:       wantFinish: d.item.finish,
1034:       wantValue: d.value,
1035:       give: offerCard,
1036:       giveValue: offerValue,
1037:       ratio,
1038:       verdict: ratio >= 1.15 ? 'good' : ratio >= .82 ? 'fair' : 'bad',
1039:     });
1040:   }
1041:   return offers;
1042: }
1043: export function acceptTrade(offerId) {
1044:   const offer = tradeOffers().find(o => o.id === offerId);
1045:   if (!offer) throw gameError('NO_OFFER', 'Trade no longer available');
1046:   const idx = state.items.findIndex(i => i.uid === offer.wantItem.uid);
1047:   if (idx < 0) throw gameError('NO_ITEM', 'Card no longer in your vault');
1048:   state.items.splice(idx, 1);
1049:   const item = addItem(offer.give.id, 'base', {source:'trade'});
1050:   state.stats.trades++;
1051:   state.daily.trades++;
1052:   state.tradeHistory.unshift({
1053:     at: Date.now(), trader: offer.trader.alias,
1054:     gaveCardId: offer.want.id, gaveFinish: offer.wantFinish, gaveSerial: offer.wantItem.serial,
1055:     gotCardId: offer.give.id, gotFinish: item.finish, gotSerial: item.serial,
1056:     value: offer.giveValue,
1057:   });
1058:   state.tradeHistory = state.tradeHistory.slice(0, 24);
1059:   addXp(25);
1060:   state.tradeSeed++;
1061:   save(); emit();
1062:   return {offer, item};
1063: }
1064: export function refreshTrades() {
