+function communitySeed() {
+  const date = (state.showroom.visited.join('|') || '0') + String(state.showroom.likes.length);
+  let h = 2166136261;
+  for (let i = 0; i < date.length; i++) h = Math.imul(h ^ date.charCodeAt(i), 16777619);
