input.content:
/* ============================================================
   Memorabilia / merchandise / marketplace expansion styles
   ============================================================ */
.legal-note{margin:0 0 20px;padding:12px 16px;border:1px solid rgba(255,194,71,.25);border-left:3px solid var(--gold);border-radius:10px;background:rgba(255,194,71,.06);color:#d8c9a9;font-size:12.5px}
.legal-note b{color:var(--gold)}

.relic-section{margin-bottom:28px}
.section-title{display:flex;align-items:baseline;justify-content:space-between;gap:12px;margin-bottom:14px}
.section-title h3{margin:0;font:700 19px var(--font-display);letter-spacing:.04em;text-transform:uppercase}
.section-title span{font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.08em}

.relic-filters{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:12px}
.relic-filters select,.rf-search{height:38px;border:1px solid var(--line);border-radius:8px;background:rgba(255,255,255,.04);color:var(--text);padding:0 11px;font-size:12px;outline:none}
.relic-filters select:focus,.rf-search:focus{border-color:rgba(255,196,83,.5)}
.rf-search{display:flex;align-items:center;gap:7px;min-width:230px;flex:1}
.rf-search span{color:var(--muted);font-size:16px}
.rf-search input{width:100%;border:0;background:none;color:inherit;outline:none;font:inherit}
.rarity-legend{display:flex;flex-wrap:wrap;gap:14px;margin:10px 0 14px;font:600 10.5px var(--font-tech);letter-spacing:.07em;text-transform:uppercase}

.relic-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(218px,1fr));gap:14px}
.relic-card{position:relative;overflow:hidden;border:1px solid color-mix(in srgb,var(--relic-accent) 35%,transparent);border-radius:14px;background:linear-gradient(160deg,rgba(255,255,255,.05),rgba(0,0,0,.35));box-shadow:0 14px 32px -20px #000,inset 0 0 26px -18px var(--relic-accent);transition:transform .18s ease,box-shadow .18s ease}
.relic-card:hover{transform:translateY(-3px);box-shadow:0 22px 40px -22px #000,0 0 0 1px color-mix(in srgb,var(--relic-accent) 60%,transparent)}
.rc-top{display:flex;justify-content:space-between;align-items:center;padding:8px 10px 4px;font:700 9px var(--font-tech);letter-spacing:.11em;color:var(--muted)}
.rc-rarity{color:var(--relic-accent)}
.rc-body{padding:4px 12px 12px}
.rc-cat{font:600 9.5px var(--font-tech);letter-spacing:.09em;text-transform:uppercase;color:var(--muted)}
.rc-body h4{margin:3px 0 8px;font:700 16px/1.2 var(--font-display);letter-spacing:.02em}
.rc-value{font:700 12px var(--font-tech);color:var(--gold);margin-bottom:8px}
.rc-foot{display:flex;justify-content:space-between;align-items:center;gap:6px}
.supply-chip,.owned-chip{font:700 9px var(--font-tech);letter-spacing:.06em;text-transform:uppercase;padding:4px 7px;border-radius:5px;background:rgba(255,255,255,.07);color:var(--muted)}
.supply-chip.open{color:var(--green);background:rgba(62,224,138,.1)}
.supply-chip.sold-out{color:var(--red-2);background:rgba(255,107,82,.12)}
.owned-chip{color:var(--cyan);background:rgba(34,211,238,.1)}
.rc-open{position:absolute;inset:0;width:100%;height:100%;background:none}

.relic-art{position:relative;height:190px;overflow:hidden;background:radial-gradient(circle at 50% 36%,color-mix(in srgb,var(--relic-rar) 16%,transparent),transparent 65%),linear-gradient(180deg,#151922,#090b10)}
.relic-art-sm{height:132px}
.relic-art-cine{height:230px}
.relic-art-grid{position:absolute;inset:0;background-image:linear-gradient(rgba(255,255,255,.035) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.035) 1px,transparent 1px);background-size:24px 24px;transform:perspective(320px) rotateX(62deg) translateY(38%);opacity:.55}
.relic-spot{position:absolute;left:50%;top:-30%;width:78%;height:130%;transform:translateX(-50%);background:radial-gradient(ellipse at center,var(--relic-glow),transparent 66%);filter:blur(4px)}
.relic-stand{position:absolute;left:50%;bottom:15px;transform:translateX(-50%);width:88px;height:11px;border-radius:50%;background:linear-gradient(180deg,rgba(255,255,255,.2),rgba(0,0,0,.7));box-shadow:0 8px 16px rgba(0,0,0,.8)}
.relic-stand::before{content:'';position:absolute;left:50%;bottom:9px;transform:translateX(-50%);width:52px;height:26px;border-left:3px solid rgba(255,255,255,.12);border-right:3px solid rgba(255,255,255,.12);background:linear-gradient(90deg,rgba(255,255,255,.06),transparent)}
.relic-stand-wall::before{display:none}
.relic-shape{position:absolute;left:50%;top:50%;width:104px;height:104px;transform:translate(-50%,-50%) rotateX(12deg) rotateY(-12deg);transform-style:preserve-3d;filter:drop-shadow(0 16px 12px rgba(0,0,0,.65))}
.relic-art-sm .relic-shape{width:74px;height:74px}
.relic-art-cine .relic-shape{width:138px;height:138px;animation:relicFloat 4s ease-in-out infinite}
.relic-glyph{position:absolute;inset:0;display:grid;place-items:center;font:400 62px/1 system-ui;color:var(--relic-c1);text-shadow:0 0 22px var(--relic-glow),2px 3px 0 var(--relic-c2)}
.relic-art-sm .relic-glyph{font-size:44px}
.relic-art-cine .relic-glyph{font-size:82px}
.relic-shine{position:absolute;inset:8% 32% 42% 12%;border-radius:50%;background:linear-gradient(160deg,rgba(255,255,255,.42),transparent 60%);transform:rotate(-18deg)}
.relic-texture{position:absolute;inset:0;opacity:.28;background-image:repeating-linear-gradient(45deg,transparent 0 4px,rgba(0,0,0,.35) 4px 5px);mix-blend-mode:overlay;border-radius:16px}
.relic-shadow{position:absolute;left:50%;bottom:8px;transform:translateX(-50%);width:112px;height:18px;background:rgba(0,0,0,.6);filter:blur(9px)}
.relic-sign{position:absolute;left:10px;bottom:9px;font:700 8.5px var(--font-script);letter-spacing:.04em;color:#fff;text-shadow:0 0 8px var(--relic-rar)}
.relic-serial-tag{position:absolute;right:9px;top:9px;font:700 8px var(--font-tech);letter-spacing:.08em;padding:3px 6px;border:1px solid var(--relic-glow);border-radius:4px;color:var(--relic-rar);background:rgba(0,0,0,.5)}
@keyframes relicFloat{0%,100%{transform:translate(-50%,-50%) rotateX(12deg) rotateY(-12deg)}50%{transform:translate(-50%,-54%) rotateX(8deg) rotateY(10deg)}}

.relic-pack-strip{display:grid;grid-template-columns:repeat(auto-fit,minmax(270px,1fr));gap:12px}
.relic-pack{display:flex;gap:11px;padding:13px;border:1px solid color-mix(in srgb,var(--pack-accent) 32%,transparent);border-radius:12px;background:linear-gradient(145deg,rgba(255,255,255,.05),rgba(0,0,0,.35))}
.rp-ico{font:400 30px system-ui;color:var(--pack-accent);text-shadow:0 0 18px var(--pack-accent)}
.rp-body{flex:1;min-width:0}
.rp-body b{display:block;font:700 15px var(--font-display)}
.rp-body span{display:block;font-size:11px;color:var(--muted);line-height:1.35}
.rp-odds{display:flex;flex-wrap:wrap;gap:5px;margin-top:6px}
.rp-odds span{font:700 8.5px var(--font-tech);padding:2px 5px;border-radius:4px;background:rgba(255,255,255,.07);color:var(--pack-accent)}
.rp-buy{display:flex;flex-direction:column;align-items:flex-end;gap:5px}
.rp-buy b{font:700 13px var(--font-tech);color:var(--gold)}

.relic-album-strip{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:11px}
.relic-album{padding:12px;border:1px solid var(--line);border-radius:11px;background:var(--panel)}
.relic-album.complete{border-color:rgba(62,224,138,.4)}
.ra-top{display:flex;justify-content:space-between;font:700 13px var(--font-display)}
.ra-top b{color:var(--gold)}
.ra-bar,.supply-bar,.prestige-bar{height:5px;margin:8px 0;border-radius:5px;background:rgba(255,255,255,.08);overflow:hidden}
.ra-bar i,.supply-bar i,.prestige-bar i{display:block;height:100%;border-radius:5px;background:linear-gradient(90deg,var(--gold),var(--cyan))}
.ra-meta{display:flex;justify-content:space-between;align-items:center;gap:6px;font-size:10.5px;color:var(--muted)}
.ra-meta .claimed{color:var(--green)}
.ra-open{width:100%;margin-top:7px;text-align:left;font:600 10px var(--font-tech);letter-spacing:.06em;color:var(--cyan)}

.owned-strip{display:flex;gap:9px;overflow-x:auto;padding:4px 2px 12px}
.owned-empty{padding:18px;border:1px dashed var(--line);border-radius:10px;color:var(--muted);font-size:12px;text-align:center}
.owned-tile{flex:0 0 108px;padding:5px;border:1px solid color-mix(in srgb,var(--relic-accent) 30%,transparent);border-radius:9px;background:rgba(255,255,255,.03);text-align:left}
.owned-tile .relic-art{height:74px;border-radius:6px}
.owned-tile .relic-stand,.owned-tile .relic-serial-tag,.owned-tile .relic-sign{display:none}
.owned-tile .relic-shape{width:46px;height:46px}
.owned-tile .relic-glyph{font-size:30px}
.owned-tile span{display:block;margin-top:5px;font:700 10px var(--font-display);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.owned-tile small{color:var(--muted);font:600 9px var(--font-tech)}

.rotating-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px}
.rotating-card,.limited-drop{display:flex;gap:10px;align-items:center;padding:10px;border:1px solid var(--line);border-radius:11px;background:var(--panel)}
