.custom-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:10px}
.custom-field{display:flex;flex-direction:column;gap:5px;font:600 10px var(--font-tech);letter-spacing:.07em;text-transform:uppercase;color:var(--muted)}
.custom-field select,.custom-field input{height:38px;padding:0 10px;border:1px solid var(--line);border-radius:8px;background:rgba(255,255,255,.04);color:var(--text);outline:none;font:600 12px var(--font-body)}
.custom-field select:focus,.custom-field input:focus{border-color:rgba(179,107,255,.6)}
.decoration-strip{display:flex;flex-wrap:wrap;gap:7px;margin-top:10px}
