const store = new Map();
globalThis.localStorage = {
  getItem: k => store.get(k) ?? null,
  setItem: (k,v) => store.set(k,v),
  removeItem: k => store.delete(k),
};
globalThis.document = {
  body: { classList: { add(){}, remove(){}, toggle(){} } },
  getElementById: () => null,
  querySelectorAll: () => [],
  addEventListener(){},
};
globalThis.window = { addEventListener(){}, dispatchEvent(){}, CustomEvent: class {} };
globalThis.btoa = s => Buffer.from(s,'binary').toString('base64');
globalThis.atob = s => Buffer.from(s,'base64').toString('binary');
globalThis.CustomEvent = class {};
globalThis.location = { hash: '' };

const base = '/home/runner/work/PlayGround/PlayGround/js/';
const cardMod = await import(base + 'data/index.js');
const relicMod = await import(base + 'data/relics.js');
const showroomMod = await import(base + 'data/showroom.js');
const storeMod = await import(base + 'store.js');

const cardIds = new Set(cardMod.CARDS.map(c => c.id));
const errors = [];
const relicIds = new Set();
for (const r of relicMod.RELICS) {
  if (relicIds.has(r.id)) errors.push(`duplicate relic id ${r.id}`);
  relicIds.add(r.id);
  if (!cardIds.has(r.baseId)) errors.push(`${r.id}: unknown base card ${r.baseId}`);
  if (!relicMod.RELIC_RARITY[r.rarity]) errors.push(`${r.id}: bad rarity ${r.rarity}`);
  if (!relicMod.CATEGORY_MAP[r.category]) errors.push(`${r.id}: bad category ${r.category}`);
  if (r.sport !== 'f1' && r.sport !== 'motogp') errors.push(`${r.id}: bad sport ${r.sport}`);
}
for (const p of relicMod.MEMORABILIA_PACKS) {
  if (!p.rarities?.length) errors.push(`${p.id}: no rarities`);
  for (const r of p.rarities || []) if (!relicMod.RELIC_RARITY[r]) errors.push(`${p.id}: bad rarity ${r}`);
}
for (const a of relicMod.RELIC_ALBUMS) {
  if (a.reward?.relicId && !relicIds.has(a.reward.relicId)) errors.push(`${a.id}: bad reward relic ${a.reward.relicId}`);
}
for (const room of showroomMod.ROOMS) {
  if (!showroomMod.ROOM_MAP[room.id]) errors.push(`room map missing ${room.id}`);
}
for (const d of showroomMod.DISPLAYS) {
  if (!showroomMod.DISPLAY_MAP[d.id]) errors.push(`display map missing ${d.id}`);
}
// exercise core flows
const s = storeMod.getState();
const pack = relicMod.MEMORABILIA_PACKS[0];
const opened = storeMod.openRelicPack(pack.id);
if (opened.results.length !== pack.cards) errors.push('pack wrong card count');
const relic = opened.results[0].relic;
const info = storeMod.relicSupplyInfo(relic);
if (relic.supply && info.issued > info.cap) errors.push('relic cap exceeded');
storeMod.buyRelic(relicMod.MERCHANDISE[0].id);
const art = await import(base + 'relic-ui.js');
if (!art.relicArtHTML(relic)) errors.push('relic art empty');
const exp = await import(base + 'screens-expansion.js');
for (const fn of [exp.memorabiliaScreen, exp.merchandiseScreen, exp.showroomScreen, exp.relicMarketPanel, exp.auctionPanel]) {
  try { const html = fn(); if (!html || typeof html !== 'string') errors.push(`${fn.name} empty`); }
  catch (e) { errors.push(`${fn.name}: ${e.message}`); }
}
console.log(`checked ${relicMod.RELICS.length} relics, ${relicMod.MEMORABILIA.length} memorabilia, ${relicMod.MERCHANDISE.length} merchandise`);
console.log(errors.length ? errors.join('\n') : 'ALL CHECKS PASSED');
process.exit(errors.length ? 1 : 0);
EOF
node /tmp/opencode/validate-expansion.mjs

