const base = 'http://localhost:9223';
const target = await (await fetch(base + '/json/new?http://localhost:3002/')).json();
const ws = new WebSocket(target.webSocketDebuggerUrl);
let id = 0;
const pending = new Map();
const events = [];
ws.addEventListener('message', ev => {
  const m = JSON.parse(ev.data);
  if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); }
  else if (m.method) events.push(m);
});
await new Promise(r => ws.addEventListener('open', r, {once:true}));
const send = (method, params = {}) => new Promise(res => { const n = ++id; pending.set(n, res); ws.send(JSON.stringify({id:n, method, params})); });
const sleep = ms => new Promise(r => setTimeout(r, ms));
await send('Runtime.enable');
await send('Log.enable');
await send('Page.enable');
await send('Page.navigate', {url:'http://localhost:3002/'});
await sleep(3500);

const evalJS = async expr => {
  const r = await send('Runtime.evaluate', {expression:expr, returnByValue:true, awaitPromise:true, userGesture:true});
  if (r.result?.exceptionDetails) return {error:r.result.exceptionDetails.text + ' ' + (r.result.exceptionDetails.exception?.description||'')};
  return r.result?.result?.value;
};

const report = [];
async function check(label, expr) {
  const v = await evalJS(expr);
  report.push(`${v && v.error ? 'FAIL' : 'PASS'} ${label}${v && v.error ? ' :: ' + v.error : ''}${typeof v === 'string' && !v.startsWith('PASS') ? '' : ''}`);
  return v;
}

// initial state
report.push('title: ' + await evalJS('document.title'));
report.push('nav items: ' + await evalJS(`[...document.querySelectorAll('#nav-main [data-nav]')].map(b=>b.dataset.nav).join(',')`));
report.push('body text length: ' + await evalJS('document.body.innerText.length'));

// Fresh save so we exercise onboarding
await evalJS(`localStorage.clear(); location.reload(); 'reload'`);
await sleep(3000);
report.push('after reset title: ' + await evalJS('document.title'));

// navigate each new screen
for (const route of ['memorabilia','merchandise','showroom','market','collection','vault','albums','home']) {
  await evalJS(`location.hash='#/${route}'; 'go'`);
  await sleep(700);
  const info = await evalJS(`({hash:location.hash, screen:document.querySelector('.screen')?.dataset.screen||'', text:document.querySelector('main')?.innerText.slice(0,90)||'', err:!!document.querySelector('.screen .empty-state')})`);
  report.push(`route ${route}: ${JSON.stringify(info)}`);
}

// market tabs
await evalJS(`location.hash='#/market'; 'go'`); await sleep(500);
for (const tab of ['relics','auctions','cards']) {
  await evalJS(`document.querySelector('[data-market-tab="${tab}"]')?.click(); 'click'`);
  await sleep(400);
  report.push(`market tab ${tab}: ` + await evalJS(`({active:document.querySelector('.market-tabs .active')?.dataset.marketTab, text:document.querySelector('main')?.innerText.slice(0,70)})`));
}

// relic pack details + open (give currency first)
await evalJS(`location.hash='#/memorabilia'; 'go'`); await sleep(500);
report.push('memorabilia screen: ' + await evalJS(`({packs:document.querySelectorAll('[data-open-relic-pack]').length, albums:document.querySelectorAll('[data-relic-album]').length, cards:document.querySelectorAll('.relic-card').length})`));
await evalJS(`document.querySelector('[data-relic-pack-details]')?.click(); 'click'`); await sleep(300);
report.push('pack details modal: ' + await evalJS(`!!document.querySelector('.relic-pack-detail')`));
await evalJS(`document.querySelector('[data-close-modal]')?.click(); 'close'`); await sleep(200);
// grant coins/gems via save edit then reload
await evalJS(`(()=>{const k=Object.keys(localStorage).find(k=>k.includes('apexrush'));const s=JSON.parse(localStorage.getItem(k));s.coins=9999999;s.gems=9999;localStorage.setItem(k,JSON.stringify(s));return k})()`);
await evalJS(`location.reload(); 'reload'`); await sleep(2500);
await evalJS(`location.hash='#/memorabilia'; 'go'`); await sleep(500);
await evalJS(`document.querySelector('[data-open-relic-pack]')?.click(); 'open'`); await sleep(700);
report.push('reveal modal: ' + await evalJS(`({reveal:!!document.querySelector('.relic-reveal'), cards:document.querySelectorAll('.reveal-card').length})`));
await evalJS(`document.querySelector('[data-close-relic-reveal]')?.click(); 'close'`); await sleep(400);
report.push('owned tiles after pack: ' + await evalJS(`document.querySelectorAll('.owned-tile').length`));

// merchandise buy
await evalJS(`location.hash='#/merchandise'; 'go'`); await sleep(500);
await evalJS(`document.querySelector('.relic-card [data-open-relic]')?.click(); 'click'`); await sleep(300);
report.push('merch detail: ' + await evalJS(`({detail:!!document.querySelector('.relic-detail'), disclaimer:document.querySelector('.rd-disclaimer')?.innerText.slice(0,60), buy:!!document.querySelector('[data-buy-relic]')})`));
await evalJS(`document.querySelector('[data-buy-relic]')?.click(); 'buy'`); await sleep(600);
report.push('after buy toast/owned: ' + await evalJS(`({toasts:document.querySelectorAll('.toast').length, modal:!!document.querySelector('.relic-detail')})`));
await evalJS(`document.querySelectorAll('[data-close-modal]').forEach(b=>b.click()); 'close'`); await sleep(300);

// showroom canvas + place item
await evalJS(`location.hash='#/showroom'; 'go'`); await sleep(900);
report.push('showroom: ' + await evalJS(`({canvas:!!document.querySelector('#showroom-canvas'), rooms:document.querySelectorAll('.room-card').length, inv:document.querySelectorAll('[data-display-item]').length, prestige:document.querySelector('.prestige-copy h3')?.innerText})`));
await evalJS(`document.querySelector('[data-display-item]')?.click(); 'click'`); await sleep(300);
report.push('display modal: ' + await evalJS(`({modal:!!document.querySelector('.display-modal'), rooms:document.querySelectorAll('#display-room option').length, displays:document.querySelectorAll('#display-type option').length})`));
await evalJS(`document.querySelector('[data-display-place]')?.click(); 'place'`); await sleep(500);
report.push('after place: ' + await evalJS(`({placed:document.querySelectorAll('.placed-row').length, toasts:[...document.querySelectorAll('.toast')].map(t=>t.innerText.slice(0,40))})`));

// room unlock + custom
await evalJS(`document.querySelector('.room-card.locked')?.click(); 'click'`); await sleep(300);
await evalJS(`document.querySelector('[data-unlock-room]')?.click(); 'unlock'`); await sleep(400);
report.push('after unlock: ' + await evalJS(`({unlocked:document.querySelectorAll('.room-card.unlocked').length, toasts:[...document.querySelectorAll('.toast')].map(t=>t.innerText.slice(0,40))})`));
await evalJS(`(()=>{const s=document.querySelector('[data-custom="layout"]');if(s){s.value='paddock';s.dispatchEvent(new Event('change',{bubbles:true}));}return !!s})()`); await sleep(500);
report.push('custom layout: ' + await evalJS(`document.querySelector('[data-custom="layout"]')?.value`));

// community visits
await evalJS(`document.querySelector('[data-visit-showroom]')?.click(); 'visit'`); await sleep(300);
report.push('visit modal: ' + await evalJS(`!!document.querySelector('.visit-modal')`));
await evalJS(`document.querySelector('[data-close-modal]')?.click(); 'close'`); await sleep(200);

// market relic buy + auction bid
await evalJS(`location.hash='#/market'; 'go'`); await sleep(500);
await evalJS(`document.querySelector('[data-market-tab="relics"]')?.click(); 'click'`); await sleep(400);
await evalJS(`document.querySelector('[data-buy-relic-listing]:not([disabled])')?.click(); 'buy'`); await sleep(500);
report.push('relic listing buy: ' + await evalJS(`({sold:document.querySelectorAll('.relic-listing.sold').length, toasts:[...document.querySelectorAll('.toast')].map(t=>t.innerText.slice(0,40))})`));
await evalJS(`document.querySelectorAll('[data-close-modal]').forEach(b=>b.click()); location.hash='#/market'; 'x'`); await sleep(300);
await evalJS(`document.querySelector('[data-market-tab="auctions"]')?.click(); 'click'`); await sleep(400);
await evalJS(`document.querySelector('[data-auction-bid]')?.click(); 'bid'`); await sleep(500);
report.push('auction bid: ' + await evalJS(`({toasts:[...document.querySelectorAll('.toast')].map(t=>t.innerText.slice(0,50)), history:document.querySelectorAll('.auction-panel .mh-row').length})`));

// old flows: pack open (card), vault
await evalJS(`location.hash='#/vault'; 'go'`); await sleep(500);
report.push('vault: ' + await evalJS(`({screen:document.querySelector('.screen')?.dataset.screen, text:document.querySelector('main')?.innerText.slice(0,70)})`));
await evalJS(`location.hash='#/packs'; 'go'`); await sleep(500);
report.push('packs: ' + await evalJS(`({open:document.querySelectorAll('[data-open-pack]').length, text:document.querySelector('main')?.innerText.slice(0,60)})`));
await evalJS(`document.querySelector('[data-open-pack]')?.click(); 'open'`); await sleep(900);
report.push('card opening: ' + await evalJS(`({opening:!!document.querySelector('#opening-root')?.innerHTML?.trim() || !!document.querySelector('.opening'), hash:location.hash})`));

const consoleErrors = events.filter(e => (e.method === 'Runtime.exceptionThrown') || (e.method === 'Log.entryAdded' && ['error'].includes(e.params?.entry?.level)) || (e.method === 'Runtime.consoleAPICalled' && e.params?.type === 'error')).map(e => {
  if (e.method === 'Runtime.exceptionThrown') return 'EXCEPTION: ' + (e.params?.exceptionDetails?.exception?.description || e.params?.exceptionDetails?.text);
  if (e.method === 'Log.entryAdded') return 'LOG: ' + e.params?.entry?.text;
  return 'CONSOLE: ' + (e.params?.args || []).map(a => a.value || a.description).join(' ');
});
report.push('--- CONSOLE ERRORS (' + consoleErrors.length + ') ---');
report.push(...consoleErrors.slice(0, 25));

console.log(report.join('\n'));
ws.close();

