const store = new Map();
globalThis.localStorage = { getItem:k=>store.get(k)??null, setItem:(k,v)=>store.set(k,v), removeItem:k=>store.delete(k) };
globalThis.document = { body:{classList:{add(){},remove(){},toggle(){}}}, getElementById:()=>null, querySelectorAll:()=>[], addEventListener(){} };
globalThis.window = { addEventListener(){}, dispatchEvent(){}, CustomEvent:class {} };
globalThis.btoa = s=>Buffer.from(s,'binary').toString('base64');
globalThis.atob = s=>Buffer.from(s,'base64').toString('binary');
globalThis.CustomEvent = class {};
globalThis.location = {hash:''};

const base = '/home/runner/work/PlayGround/PlayGround/js/';
const S = await import(base+'store.js');
const R = await import(base+'data/relics.js');
const SH = await import(base+'data/showroom.js');
const C = await import(base+'data/index.js');
const errors = [];
const ok = (cond,msg) => { if(!cond) errors.push(msg); };

// fund
let s = S.getState(); s.coins = 5_000_000; s.gems = 10_000; s.collectorTokens = 1000;

// complete an album by adding every relic in it
const album = R.RELIC_ALBUMS.find(a=>a.id==='rel-artefacts');
const pool = R.relicsForAlbum(album);
for (const r of pool) { try { S.addRelic(r.id,{source:'test'}); } catch(e) { errors.push(`addRelic ${r.id}: ${e.message}`); } }
let prog = S.relicAlbumProgress(album);
ok(prog.complete, `album ${album.id} should be complete (${prog.have}/${prog.total})`);
const coinsBefore = S.getState().coins, tokensBefore = S.getState().collectorTokens;
const claim = S.claimRelicAlbum(album.id);
ok(S.getState().coins > coinsBefore, 'album coin reward applied');
ok(S.getState().collectorTokens > tokensBefore, 'album token reward applied');
ok(S.getState().showroom.custom.decorations.includes(album.reward.decoration), 'album decoration unlocked');
ok(!!claim.bonus, 'album bonus relic granted');

// cap enforcement: museum item supplied 5 -> cannot issue 6
const museum = R.MEMORABILIA.find(r=>r.supply===5);
let issued=0;
while (issued < 5) { try { S.addRelic(museum.id,{source:'test'}); issued++; } catch(e) { errors.push(`museum issue ${issued}: ${e.message}`); break; } }
let overflow=false;
try { S.addRelic(museum.id,{source:'test'}); overflow=true; } catch(e) { ok(e.code==='SOLD_OUT','museum overflow should be SOLD_OUT'); }
ok(!overflow,'museum cap must block a 6th serial');
const info = S.relicSupplyInfo(museum);
ok(info.issued===5 && info.remaining===0 && new Set(info.serials).size===5,'museum serial ledger correct');

// showroom: unlock room with requirement met
s = S.getState();
for (const c of C.CARDS.filter(c=>c.sport==='f1').slice(0,25)) S.addItem(c.id);
const f1room = SH.ROOM_MAP.f1;
const status = S.roomStatus('f1');
ok(status.reqMet,`f1 room requirement should be met: ${JSON.stringify({cards:new Set(S.getState().items.map(i=>i.cardId)).size, status})}`);
const roomsBefore = S.getState().showroom.rooms.length;
S.unlockRoom('f1');
ok(S.getState().showroom.rooms.length===roomsBefore+1,'f1 room unlocked');
let roomLocked=false; try { S.unlockRoom('f1'); roomLocked=true; } catch(e){ ok(e.code==='ALREADY_UNLOCKED','double unlock rejected'); }
ok(!roomLocked,'cannot unlock same room twice');

// place / hide / remove
const owned = S.ownedRelics()[0];
const placed = S.placeShowroomItem(owned.item.uid,'relic','main','pedestal');
ok(!!placed.fixture,'relic placed in main room');
const placement = S.getState().showroom.items.find(i=>i.itemUid===owned.item.uid);
ok(!!placement,'placement recorded');
ok(S.toggleShowroomVisible(placement.uid)===false,'visible toggles to hidden');
ok(S.toggleShowroomVisible(placement.uid)===true,'visible toggles back');
S.removeShowroomItem(placement.uid);
ok(!S.getState().showroom.items.some(i=>i.uid===placement.uid),'placement removed');

// sell keeps serial in ledger
const sellTarget = S.ownedRelics().find(e=>e.relic.supply && e.item.serial!=null);
const serial = sellTarget.item.serial;
const sold = S.sellRelicItem(sellTarget.item.uid);
ok(sold.value>0,'sale returns value');
ok(S.relicSupplyInfo(sellTarget.relic).serials.includes(serial),'sold serial remains issued in ledger');

// auctions & market buy
const listing = S.relicMarketListings()[0];
const before = S.getState().coins;
S.buyRelicListing(listing.id);
ok(S.getState().coins < before,'market buy spends coins');
const lot = S.auctionLots()[0];
const bid = S.placeAuctionBid(lot.id, lot.buyNow);
ok(bid.won,'buy-now wins auction');
ok(S.getState().stats.auctionsWon>=1,'auction win stat recorded');

// community
S.likeShowroom('ApexCollector'); S.visitShowroom('ApexCollector');
const comm = S.communityShowrooms();
ok(comm.find(c=>c.alias==='ApexCollector').liked,'community like persisted');
ok(S.getState().showroom.visits>0,'visit counter advanced');

// prestige
const prest = S.showroomPrestige();
ok(prest.level>=1 && prest.name,'prestige computed');

console.log(errors.length ? errors.join('\n') : 'ALL FLOW CHECKS PASSED');
process.exit(errors.length?1:0);

