const target = await (await fetch('http://localhost:9223/json/new?http://localhost:3002/#/showroom', {method:'PUT'})).json();
const ws = new WebSocket(target.webSocketDebuggerUrl);
let id=0; const pending=new Map();
ws.addEventListener('message',ev=>{const m=JSON.parse(ev.data);if(m.id&&pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id);}});
await new Promise(r=>ws.addEventListener('open',r,{once:true}));
const send=(method,params={})=>new Promise(res=>{const n=++id;pending.set(n,res);ws.send(JSON.stringify({id:n,method,params}));});
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
await send('Runtime.enable'); await sleep(3000);
const r = await send('Runtime.evaluate',{expression:`(()=>{const c=document.querySelector('#showroom-canvas');if(!c)return 'no canvas';const ctx=c.getContext('2d');const d=ctx.getImageData(0,0,c.width,c.height).data;let lit=0,colors=new Set();for(let i=0;i<d.length;i+=4*97){if(d[i]+d[i+1]+d[i+2]>60){lit++;colors.add(d[i]+','+d[i+1]+','+d[i+2]);}}return JSON.stringify({w:c.width,h:c.height,sampled:Math.floor(d.length/(4*97)),lit,distinctColors:colors.size,dataUrl:c.toDataURL().length});})()`,returnByValue:true});
